# November 22, 2026: northern and western Clinton County, New York (Plattsburgh's downtown and old Army post, Rouses
# Point, Champlain, Chazy, Altona, Dannemora and Lyon Mountain). Drawn at random by tools/choose.py --state ny (region
# adk, which offered Champlain); start.py found no Atlas place within 20 km of Champlain, and only the Kent-Delord House
# and the Old Stone Barracks in Plattsburgh. Sources were opened in this session: Wikipedia as raw text; HMdb marker
# pages (texts and positions); the Lake Champlain Maritime Museum's 2019 battlefield report for the City of Plattsburgh
# (American Battlefield Protection Program grant 2887-16-009); the Village of Rouses Point's welcome-centre page; the
# Episcopal Diocese of Albany's Trinity Church page; the Diocese of Ogdensburg's Plattsburgh parish page; the Alice T.
# Miner Museum's own pages; Miner Institute's heritage-exhibit page; the Clinton County Historical Association's home
# page; the Friends of Lyon Mountain's blog; Adirondack Explorer (Million Dollar Dam); WAMC (the Strand, September 2026).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HM(n,t): return ['HMdb: '+t,'https://www.hmdb.org/m.asp?m=%d'%n]
ABPP=L('Lake Champlain Maritime Museum for the City of Plattsburgh: document review and archaeological assessment (ABPP grant 2887-16-009)','https://cityofplattsburgh-ny.gov/sites/cityofplattsburgh.com/files/city-historian/ABPP2887-16-009FinalDrafte311.pdf')
MINER=L('Miner Institute: Heart\'s Delight Farm Heritage Exhibit','https://whminer.org/facility/hearts-delight-farm-heritage-exhibit')
AEX=L('Adirondack Explorer: Million Dollar Dam, a walk through history','https://www.adirondackexplorer.org/?p=306204')

BATCH={'key':'adk_jqar','label':'Northern Clinton County: Plattsburgh, Rouses Point, Chazy, Altona and Lyon Mountain','added':'2026-11-22 15:59'}

PLACES=[
# ---- Plattsburgh: downtown ----
N('plattsburgh-city-hall','Plattsburgh City Hall','Plattsburgh','adk','civic','standing',44.69921,-73.45187,'exact','view','drive','','1917',
  'The city hall, built in 1917 to a design by John Russell Pope: three storeys on a steel frame, faced in limestone, in the Classical Revival style. The city\'s marker says Pope later used its classical lines for the Jefferson Memorial in Washington. It was listed on the National Register in 1973.',
  'A portico of six Doric columns and a low central dome facing City Hall Place (US 9), with the Macdonough Monument in front and Trinity Church beside it. Interior not checked.',
  'The small-city rehearsal for the Jefferson Memorial.',
  'A working city building on City Hall Place; seen from the street and the square. Street parking downtown.',
  [W('City Hall (Plattsburgh, New York)'),HM(115220,'City Hall - 1917')],brick='no'),
N('macdonough-monument-plattsburgh','Macdonough Monument','Plattsburgh','adk','curio','standing',44.69897,-73.45139,'exact','public','drive','','1926',
  'A 135-foot memorial, designed by John Russell Pope and put up in 1926, to the American naval victory at the Battle of Plattsburgh in September 1814, when Thomas Macdonough\'s squadron beat the British fleet in the bay. The obelisk is one of the three parts of the Plattsburgh Bay National Historic Landmark, with the bay itself and the site of Fort Brown.',
  'The tall shaft on the square in front of City Hall, with older Macdonough tablets round it (HMdb lists three markers here).',
  'The battle that ended the last British invasion from the north, remembered in a downtown square.',
  'On the public square at City Hall Place and Trinity Place. Street parking downtown.',
  [HM(110157,'Macdonough Monument - 1926'),HM(47946,'MacDonough Monument'),ABPP],brick='?'),
N('trinity-episcopal-church-plattsburgh','Trinity Episcopal Church','Plattsburgh','adk','worship','standing',44.69893,-73.45258,'exact','open','drive','','1830',
  'A stone church of 1830 for a parish incorporated in 1821, with a square bell tower that the diocese likens to Norman work. The city\'s marker calls it Plattsburgh\'s oldest public building. John Henry Hopkins, who wrote the carol "We Three Kings", was rector here (the marker gives 1872 to 1877 in English and 1827 to 1877 in French).',
  'The stone church on Trinity Place beside City Hall. The diocese says a dozen 19th-century memorial windows line all its sides. Open for its services (times below); interior not otherwise checked.',
  'The oldest public building in town, and the "We Three Kings" rector.',
  'An active Episcopal parish at 18 Trinity Place. Service times are from the Episcopal Diocese of Albany\'s page for the church. Street parking downtown.',
  [HM(115224,'Trinity Episcopal Church - 1830'),L('Episcopal Diocese of Albany: Trinity Church, Plattsburgh','https://albanyepiscopaldiocese.org/trinity-church-plattsburgh-ny')],
  conf='mixed',brick='no',hours='Sunday 8 and 10 a.m.; Wednesday 10 a.m. (September to May)'),
N('first-presbyterian-church-plattsburgh','First Presbyterian Church','Plattsburgh','adk','worship','standing',44.69734,-73.45445,'exact','view','drive','','1812–1816; rebuilt 1868–1873',
  'The congregation formed formally in 1797. Its first church here was built between 1812 and 1816; after a fire in 1867 it was rebuilt on the same spot between 1868 and 1873 as a rectangular limestone Gothic Revival church. It was listed on the National Register in 1982.',
  'Limestone walls with buttresses, a slate gable roof, pointed openings and a square central tower with a tall spire and a clock on each face; plaques on the side wall. Interior not checked.',
  '',
  'An active church at 34 Brinkerhoff Street; no page of its own with service times was found. Seen from the street. Street parking downtown.',
  [W('First Presbyterian Church (Plattsburgh, New York)'),HM(268197,'First Presbyterian Church of Plattsburgh')],brick='no',hours='?'),
N('st-john-the-baptist-church-plattsburgh','St. John the Baptist Church and Rectory','Plattsburgh','adk','worship','standing',44.69563,-73.45459,'exact','view','drive','','1874; rectory 1909–1910',
  'A large masonry Catholic church of 1874, cruciform, with Gothic Revival pointed arches, buttresses and a spired tower topped by a stone cross. The three-storey rectory of 1909 to 1910 mixes Colonial Revival and Gothic Revival with a half-mansard roof and a balcony. Both were listed on the National Register together in 1982.',
  'The spired church and its rectory on Broad Street. Interior not checked.',
  '',
  'A worship site of Holy Cross Parish (Diocese of Ogdensburg), at 18 to 20 Broad Street. The parish\'s own site refused to open when this was written, so no Mass times are given. Seen from the street. Street parking.',
  [W('St. John the Baptist Roman Catholic Church (Plattsburgh, New York)'),L('Diocese of Ogdensburg: Plattsburgh parishes','https://rcdony.org/parish/plattsburgh')],brick='?',hours='?'),
N('strand-theatre-plattsburgh','Strand Theatre (Strand Center Theatre)','Plattsburgh','adk','civic','standing',44.69679,-73.4546,'exact','open','drive','','1924',
  'Plattsburgh\'s premier theatre when it opened in 1924, Classical Revival, with 950 seats. It showed films without a break until 2005, when the North Country Cultural Center for the Arts (now the Strand Center for the Arts) bought it and spent ten years and $4 million restoring it. Listed on the National Register in 2008. In September 2026 the arts centre told WAMC it might have to close for lack of money; shows were still being sold for October 2026.',
  'Vestibule, lobby, mezzanine and the restored auditorium; you go in by buying a ticket for a show. The arts centre\'s gallery is in the old Federal Building next door.',
  'A 1924 movie palace brought back by its town, now fighting to stay open.',
  'Run by the Strand Center for the Arts, 25 Brinkerhoff Street; open for performances (see its calendar). Whether it is still operating after autumn 2026 was not checked. Street parking downtown.',
  [W('Strand Theater (Plattsburgh, New York)'),HM(255620,'Strand Theatre'),L('WAMC: Strand Center for the Arts could close (September 9, 2026)','https://www.wamc.org/news/2026-09-09/plattsburghs-strand-center-for-the-arts-could-close-due-to-financial-crisis')],
  brick='?',hours='?'),
N('clinton-county-courthouse-plattsburgh','Old Clinton County Courthouse and Surrogate\'s Building','Plattsburgh','adk','civic','standing',44.69894,-73.45331,'site','view','drive','','1884–1889',
  'The county courthouse of 1889, two storeys of ashlar stone and brick in the Richardsonian Romanesque style, with rock-faced arches and a big square tower ending in an open bell stage and a pyramid roof. Beside it is the Surrogate\'s Building of 1884 to 1885, two storeys of brick, Italianate with a bracketed cornice. The complex was listed on the National Register in 1982.',
  'The tower and arches at 135 Margaret Street, and the smaller Italianate building beside it. Interior not checked; whether the courts still sit here was not checked.',
  '',
  'Seen from Margaret Street. Street parking downtown.',
  [W('Clinton County Courthouse Complex')],brick='yes'),
N('plattsburgh-dh-station','Plattsburgh station (Delaware and Hudson depot)','Plattsburgh','adk','rail','standing',44.6967,-73.44647,'site','view','drive','stations','1886',
  'The Delaware and Hudson Railway\'s depot of 1886, designed by the Albany architects Fuller & Wheeler in a French Provincial style. It was listed on the National Register in 1982 as the D & H Railroad Complex. Amtrak\'s Adirondack still stops once a day each way; Amtrak uses a small office at track level and the floor above holds private offices.',
  'The depot beside the single track below the downtown bluff. Interior not checked.',
  '',
  'Privately owned offices with an Amtrak stop (Wikipedia); seen from the street and the platform. An active railroad: stay off the track.',
  [W('Plattsburgh station')],brick='?'),
N('plattsburgh-barracks-us-oval','Plattsburgh Barracks and the U.S. Oval','Plattsburgh','adk','fort','standing',44.68287,-73.44781,'site','open','drive','forts','1814; post buildings 1893–1930s',
  'There was an Army post here from December 1814. Rumours in the 1880s that it would close led to a permanent post built round a parade oval from 1893 to 1897, enlarged until the mid-1930s; it was an active Army post until 1944 and then part of Plattsburgh Air Force Base, which closed in 1995. The markers name the Headquarters building at the head of the oval, overlooking the site of Fort Moreau of 1814; the Officers\' Mess of 1894; two of three troop barracks of 1893 to 1897 (the third burned in 1974 and was razed); and the Memorial Chapel of 1933, built of weathered brick taken from an older building near Plattsburgh.',
  'The oval and its ring of 1890s buildings, each with a marker. Two museums stand on the old base: the Clinton County Historical Association\'s museum (98 Ohio Avenue; four galleries and a library; hours below) and the Battle of Plattsburgh Association\'s War of 1812 Museum (11 Washington Way; its site would not open when this was written, so its hours are not given). The Old Post Cemetery (1812 to 1970) is on US 9 just south.',
  'The third-oldest military post in the country, now a park, condos and museums.',
  'The oval is public ground (the federal map shows US Oval Park); the buildings are in private and public use. Hours are from the Clinton County Historical Association\'s home page. A mapped lot on New York Road at the oval.',
  [HM(47531,'Headquarters Plattsburgh Barracks'),HM(76385,'Officers\' Mess Plattsburgh Barracks'),HM(47380,'Troop Barracks'),HM(47944,'Memorial Chapel'),HM(47375,'Old Post Cemetery'),W('Plattsburgh Air Force Base'),W('War of 1812 Museum (Plattsburgh)'),L('Clinton County Historical Association','https://clintoncountyhistorical.org/')],
  th=[44.68564,-73.44658],thn='Lot on New York Road at the U.S. Oval',brick='yes',hours='County museum: Wednesday to Saturday 10 a.m. to 3 p.m., and by appointment'),
N('fort-brown-plattsburgh','Fort Brown earthworks','Plattsburgh','adk','fort','traces',44.68797,-73.45006,'site','public','walk','forts','1814',
  'A redoubt of eight guns and four interior buildings on the bluff above the Saranac River, the left flank of the American line in the Battle of Plattsburgh, September 6 to 11, 1814, held by men of the 30th and 31st Infantry. The 1978 Register form described a roughly five-sided ring of grassy, eroded earthworks with a well-defined ditch on the south side running from Peru Street to the edge of the bluff. It is part of the Plattsburgh Bay National Historic Landmark.',
  'The parapets and ditch, best seen when the leaves are down: a December 2018 visit for the city found the earthworks much as the 1978 form describes them, with trees now blocking the old view up and down the river. A Daughters of the American Revolution marker on Peru Street (US 9) says the embankment is all that remains.',
  'The one Battle of Plattsburgh fort you can still walk round.',
  'Wikipedia says the site is now Fort Brown Park, run by the City of Plattsburgh; the city\'s own park page was not read. On Peru Street (US 9) south of New Jersey Street. The nearest mapped public lot is on New York Road at the U.S. Oval, about 400 m south-east.',
  [W('Fort Brown Site'),HM(46964,'Fort Brown'),ABPP],th=[44.68564,-73.44658],thn='Lot on New York Road at the U.S. Oval',brick='no'),
N('hawkins-hall-plattsburgh','Hawkins Hall, SUNY Plattsburgh','Plattsburgh','adk','civic','standing',44.69728,-73.46745,'exact','view','drive','','1932',
  'Built in 1932 for the State Normal School, to replace a building that burned in 1929; designed by the state architect William E. Haugaard in a Late Gothic Revival style, in stone, with a five-storey and a two-storey tower. It was named in 1955 for George Hawkins, the school\'s principal from 1898 to 1932. After nearly 60 years without much work it was restored in two stages from 1991. Listed on the National Register in 1982.',
  'The towered stone hall on Beekman Street, with large panelled wooden doors under round transoms. Interior not checked.',
  '',
  'A working university building on the SUNY Plattsburgh campus; seen from the street. Campus parking rules not checked.',
  [W('Hawkins Hall'),HM(106301,'State Normal School')],brick='no'),
# ---- Rouses Point and Champlain ----
N('fort-montgomery-rouses-point','Fort Montgomery ("Fort Blunder") ruins','Rouses Point','adk','fort','ruins',45.00606,-73.3488,'site','view','drive','forts','1844–1871',
  'The first American fort on this point, begun in 1816, was abandoned when a new survey put the 45th parallel south of it, in Canada, and locals carried off its stone: hence "Fort Blunder". The Webster-Ashburton Treaty of 1842 gave Island Point to the United States, and a second, moated stone fort was built here from 1844 to 1871. Its armament was removed in 1900 and the government sold it at auction in 1926; most of it was pulled down in 1936-37, a third surviving bastion fell into the moat in 1980, and preservationists fear more collapse. It was bought privately in 2022.',
  'Wikipedia lists what was left after 1937 as the gutted west-facing officers\' quarters, a small part of the south wall and three bastions, two of which remain. A state marker stands on Bridge Road at Montgomery Street.',
  'The fort built in the wrong country, then built again.',
  'Private land (Wikipedia: bought in 2022 and undeveloped). Do not go on without the owners\' leave. Whether the ruin can be seen well from a public road or the US 2 bridge was not checked.',
  [W('Fort Montgomery (Lake Champlain)'),HM(49070,'Fort Montgomery')],brick='?'),
N('rouses-point-dh-station','Rouses Point station (History and Welcome Center)','Rouses Point','adk','rail','standing',44.99523,-73.37103,'exact','open','drive','stations','1889',
  'The Delaware and Hudson Railway built this Romanesque brick and stone station in 1889 at Pratt Street, just south of the diamond where its line crossed the Central Vermont\'s. The village bought it for $5,000 in 2002, and with the Rouses Point-Champlain Historical Society restored it (largely with federal stimulus money) as the History and Welcome Center. Amtrak\'s Adirondack still stops here. Listed on the National Register in 2005.',
  'The restored station at 68 Pratt Street, run by the historical society, with free admission. A marker by the door.',
  'A border-town junction station saved for $5,000.',
  'Owned by the Village of Rouses Point; hours from the village\'s page. Amtrak platform on the east side: stay off the track.',
  [W('Rouses Point station'),L('Village of Rouses Point: History and Welcome Center','https://rousespointny.com/residents_and_visitors/history_and_welcome_center/'),HM(175095,'Site of Delaware and Hudson Railroad Station')],
  brick='?',hours='Saturdays through Labor Day weekend, 10 a.m. to 2 p.m.'),
N('overton-corners-border-station','Overton Corners border inspection station','Champlain','adk','civic','standing',45.00975,-73.40078,'exact','view','drive','','1931–1932',
  'One of seven US border inspection stations built along the New York-Canada line from 1931 to 1934, after Prohibition made this crossing one of the busiest on the border. Designed in the office of the Supervising Architect of the Treasury under James A. Wetmore, with Louis A. Simon over the architectural section, it is Georgian Revival in red brick with brick quoins and cast-stone keystones, and was finished in 1932, a year before Prohibition ended. Listed on the National Register in 2014.',
  'The red-brick station with its wings and a truck dock on NY 276 at the line, still in use.',
  'Built to stop bootleggers, finished just as Prohibition ended.',
  'A working federal port of entry. Driving up to it means presenting yourself for inspection: look from the road south of it, and do not stop or turn in the inspection lanes.',
  [W('Overton Corners–Lacolle 221 Border Crossing')],brick='yes'),
N('pliny-moore-house-champlain','Pliny Moore House','Champlain','adk','landmark','standing',44.98679,-73.44501,'area','view','drive','','1801',
  'Pliny Moore, a Revolutionary War veteran, settled Champlain in 1789 and in 1801 built a Federal-style frame house; he was the town\'s first judge and postmaster. In the War of 1812 the house was General Dearborn\'s headquarters in November 1812, prisoner-of-war talks took place here in 1814, and the British militia captain Mailloux, ambushed in revenge for Colonel Forsyth\'s death, died in its basement. The marker says Moore built a house "similar to the one standing today", so whether the house now standing is his own was not settled.',
  'A Federal-style frame house on Elm Street near Oak Street, with a Champlain Valley National Heritage Partnership panel. Interior not checked.',
  'A judge\'s house that both armies used as a hotel.',
  'Private; seen from Elm Street, where the panel stands.',
  [HM(177320,'Pliny Moore House')],conf='mixed',brick='no'),
N('point-au-fer-white-house-site','Point au Fer and the "White House" garrison site','Champlain','adk','fort','marker',44.94525,-73.35278,'area','view','drive','forts','1774–1805',
  'In 1774 the British built a two-storey white stone garrison, the "White House", on Point au Fer. Americans held it from May 1775; General John Sullivan added an entrenchment and a 12-foot stockade in 1776, and Benjamin Franklin, Benedict Arnold and others stopped here. Half of Burgoyne\'s army camped here in 1777, and the British kept the post until 1796, after the Jay Treaty. The building burned in 1805.',
  'Two markers on Point au Fer Road. The Friends of Champlain panel says the creek at the corner was Sullivan\'s entrenchment; nothing of the building is said to stand.',
  '',
  'Markers on the public road; the land round them was not checked and is taken to be private.',
  [HM(49069,'The "White House"'),HM(234761,'Point au Fer Historic Site')],brick='no'),
# ---- Chazy and Altona: the Miner country ----
N('alice-t-miner-museum','Alice T. Miner Museum','Chazy','adk','landmark','standing',44.88628,-73.43568,'exact','open','drive','','1924',
  'Opened in 1924 by Alice T. Miner, an early figure in the Colonial Revival, wife of the railroad-equipment inventor William H. Miner. Fifteen rooms hold period furniture, miniature furniture, china, glass, early samplers and textiles, War of 1812 muskets, Revolutionary War cannonballs and dolls. Listed on the National Register in 2010.',
  'Guided tours only, free; the museum says appointments are not needed except for groups of ten or more.',
  'A 1920s collector\'s house full of the colonial past.',
  'Run by the museum at 9618 US 9. Hours from its own page. Parking is behind the museum: from Route 9 turn onto Miner Farm Road and right into the Chazy Central Rural School bus loop.',
  [W('Alice T. Miner Museum'),L('Alice T. Miner Museum: contact and hours','https://www.minermuseum.org/contact')],
  brick='?',hours='May to December, Tuesday to Saturday 10 a.m. to 4 p.m.; guided tours only'),
N('chazy-central-rural-school','Chazy Central Rural School','Chazy','adk','civic','standing',44.88659,-73.4329,'site','view','drive','','1916',
  'William H. Miner founded the school; a 1966 marker by the Chazy Yorkers Club says it was the first central school in New York State and in the country, dated November 14, 1916. Miner gave it thirteen school buses, which were kept at his farm.',
  'The school on Miner Farm Road, still the town\'s school. Interior not checked.',
  'Where the American consolidated rural school began, by its own marker\'s claim.',
  'A working school: look from Miner Farm Road, not during the school day\'s comings and goings.',
  [HM(107203,'Chazy Central'),W('William H. Miner'),MINER],brick='?'),
N('hearts-delight-farm-chazy','Heart\'s Delight Farm (Miner Institute)','Chazy','adk','inst','standing',44.88893,-73.46628,'area','open','walk','','1903',
  'From 1903 William H. Miner turned his family\'s 144-acre homestead into a model farm of some 300 buildings on 15,000 acres with 800 workers, run on hydroelectric power and the latest science, shipping hams, sausages and eggs to hotels in New York and Chicago. Since 1951 the land has been the William H. Miner Agricultural Research Institute, a working dairy and research farm. Only a handful of the original buildings survive; the Alice T. Miner Museum names the 1906 dairy barn as one.',
  'The Heritage Exhibit in the farm\'s original storehouse (a diorama of the farm about 1910, a model of the 46-room Heart\'s Delight Cottage, Miner\'s railroad inventions), farm vehicles in the Coach House, and a wayside walk of ten panels through the gardens, among them the stone entrance gates and Happy Hours Cottage. The institute says the exhibit and walk are free and open to the public; it gives no hours.',
  'A railroad fortune\'s model farm, still farming.',
  'Private land of the Miner Institute, which welcomes visitors to the exhibit and the wayside walk. The pin is the institute\'s position in Wikipedia; the exhibit building was not placed exactly. The Heart\'s Delight marker is on Miner Farm Road west of Ridge Road.',
  [W('Miner Institute'),MINER,L('Alice T. Miner Museum: Heart\'s Delight Farm historical marker','https://www.minermuseum.org/post/heart-s-delight-farm-historical-marker'),HM(176294,'Heart\'s Delight')],
  brick='?',hours='?'),
N('trombly-log-home-chazy','1805 Trombly log home','Chazy','adk','landmark','standing',44.87213,-73.39076,'area','view','drive','','1805',
  'A log house built in 1805 by John B. Trombly, who raised eleven children. The Town of Chazy\'s marker calls it the oldest inhabited log home in Clinton County.',
  'The marker stands on Lake Shore Road about 0.2 miles north of Minkler Road; the house was not placed exactly and whether it is still lived in was not checked.',
  '',
  'A private home: look from Lake Shore Road only.',
  [HM(106114,'1805 Log Home')],conf='mixed',brick='no'),
N('million-dollar-dam-altona','Million Dollar Dam (Altona Dam) and Skeleton Dam','Altona','adk','water','ruins',44.83747,-73.57193,'site','permit','hike','','1911–1922',
  'William H. Miner\'s largest dam, a reversed slab-and-buttress wall of concrete almost half a mile long and 30 feet high, built from 1911 in 22 months by about 500 men working round the clock on the Flat Rock sandstone barrens. The porous ground leaked, and even a concrete floor poured behind it (23,000 more cubic yards) did not stop it; its powerhouse ran only from 1915 to 1922. A second, upper dam a mile upstream, the Skeleton Dam, was never finished. A hole was later blasted through the main dam.',
  'The long buttressed wall standing over the jack-pine barrens, the concrete floor ("scar pit") behind it, a concrete road along it, and the unfinished Skeleton Dam at Chasm Lake. Trails are unmarked; the institute hands out a map.',
  'A million-dollar dam that never held its water.',
  'Owned by the Miner Institute. Adirondack Explorer says the site is open to the public January through August with permission: get the permit and map at the farm office of the Miner Institute in Chazy, then drive to the gate near the dam. Adirondack Architectural Heritage runs tours. The pin is the dam as OpenStreetMap maps it; no parking point was found.',
  [AEX,W('Miner Institute'),L('Clinton County Historical Association: Altona Flat Rock','https://www.clintoncountyhistorical.org/news/hc-altona-flat-rock')],brick='no'),
N('mcgregor-powerhouse-altona','McGregor Powerhouse','Altona','adk','industry','standing',44.8805,-73.65574,'area','view','drive','','1923–1961',
  'William H. Miner built the McGregor Powerhouse and the LaSalle Dam in 1923. It was the last of his powerhouses to run, shutting down in 1961. Adirondack Explorer describes a six-storey building in the Spanish Mission style that also held apartments for employees.',
  'Adirondack Explorer says the building still stands and can be seen from Devils Den Road. The town marker is at the entrance to Feinberg Park.',
  'A Spanish Mission powerhouse in the Chazy River woods.',
  'Ownership of the building not checked: look from Devils Den Road. The pin is the marker at the entrance to Feinberg Park, about a mile south of Miner Farm Road.',
  [HM(106442,'McGregor Powerhouse'),AEX],conf='mixed',brick='?'),
# ---- Dannemora and Lyon Mountain ----
N('clinton-prison-dannemora','Clinton Prison wall, Dannemora','Dannemora','adk','inst','standing',44.7219,-73.72344,'area','view','drive','','1845; wall 1887',
  'Work on the state\'s third-oldest prison began in February 1845. At first its convicts were sent to work in the iron mines of Dannemora and Lyon Mountain; that did not pay, and mining ended by 1877. The 60-foot walls built in 1887 still stand, and inside them is the Church of St. Dismas, the Good Thief, built by inmates from 1939 to 1941. It is still the state\'s largest maximum-security prison, Clinton Correctional Facility.',
  'The long, high wall that lines the north side of NY 374 through the village. Nothing inside can be visited.',
  'Little Siberia: a prison town built round a wall.',
  'A working maximum-security prison. Look from NY 374 and the village streets only; do not stop by the gates or photograph staff or inmates.',
  [W('Clinton Correctional Facility'),HM(177608,'Clinton Prison')],brick='?'),
N('lyon-mountain-station','Lyon Mountain station (Mining and Railroad Museum)','Lyon Mountain','adk','rail','standing',44.72652,-73.91038,'exact','open','drive','stations','1903',
  'A long one-storey wooden depot with a hipped roof, wide eaves and a cupola, built by the Delaware and Hudson in 1903 for the iron-mining town. Trains stopped until 1949-50; it was then a post office and a tavern, and it is now the Friends of Lyon Mountain\'s museum of the mines and the railroad. Listed on the National Register in 2002.',
  'The cupola-topped depot in the hamlet, with exhibits on the Lyon Mountain mines and the D&H.',
  'The depot of a company iron town, kept by the town.',
  'Run by the Friends of Lyon Mountain. The newest hours on their blog are for 2015 (Wednesdays and Saturdays, 10 a.m. to 2 p.m., mid-June to late September); current hours not checked.',
  [W('Lyon Mountain station'),W('Lyon Mountain, New York'),L('Friends of Lyon Mountain: museum blog','https://lyonmountainmuseum.blogspot.com')],brick='no',hours='?'),
]

